using System.Security.Claims;using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Fiscalization;using DadoRetail.Domain.Inventory;using DadoRetail.Domain.Payments;using DadoRetail.Domain.Sales;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;
[ApiController,Route("api/v1/returns")]public sealed class ReturnsController(DadoRetailDbContext db,IEnumerable<IFiscalizationProvider> fiscalProviders):ControllerBase{
[HttpPost,HasPermission(Permissions.SaleRefund)]public async Task<IActionResult>Create(CreateReturnRequest r,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var cashierId))return Unauthorized();var sale=await db.Sales.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==r.SaleId,ct);if(sale is null)return NotFound(new{message="Исходный чек не найден"});if(sale.Status!=SaleStatus.Completed)return Conflict(new{message="Возврат возможен только по завершенному чеку"});var ret=new SaleReturn(sale.Id,sale.WarehouseId,cashierId);foreach(var line in r.Items){var sold=sale.Items.Where(x=>x.ProductId==line.ProductId).Sum(x=>x.Quantity);var returned=await db.SaleReturnItems.Where(x=>x.ProductId==line.ProductId&&db.SaleReturns.Any(y=>y.Id==x.SaleReturnId&&y.SaleId==sale.Id&&y.Status==SaleReturnStatus.Completed)).SumAsync(x=>(decimal?)x.Quantity,ct)??0;if(line.Quantity<=0||returned+line.Quantity>sold)return BadRequest(new{message="Количество возврата превышает проданное",line.ProductId,sold,returned});var unitPrice=sale.Items.First(x=>x.ProductId==line.ProductId).UnitPrice;ret.AddItem(line.ProductId,line.Quantity,unitPrice);}if(!ret.Items.Any())return BadRequest(new{message="Нет товаров для возврата"});db.SaleReturns.Add(ret);await db.SaveChangesAsync(ct);return Ok(new{ret.Id,ret.SaleId,ret.Status,ret.Total,ret.Items});}
[HttpPost("{id:guid}/complete"),HasPermission(Permissions.SaleRefund)]public async Task<IActionResult>Complete(Guid id,CancellationToken ct){var ret=await db.SaleReturns.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);if(ret is null)return NotFound();if(ret.Status==SaleReturnStatus.Completed)return Ok(new{ret.Id,ret.Status,ret.Total});var provider=fiscalProviders.FirstOrDefault();if(provider is null)return StatusCode(503,new{message="Фискальный провайдер возврата не настроен"});ret.BeginFiscalization();await db.SaveChangesAsync(ct);var fiscal=await provider.RefundAsync(ret.SaleId,ret.Total,ct);if(!fiscal.Success){ret.Fail();await db.SaveChangesAsync(ct);return StatusCode(502,new{message="Ошибка фискального возврата",fiscal.Error});}await using var tx=await db.Database.BeginTransactionAsync(ct);foreach(var item in ret.Items){var balance=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==ret.WarehouseId&&x.ProductId==item.ProductId,ct);if(balance is null){balance=new StockBalance(ret.WarehouseId,item.ProductId);db.StockBalances.Add(balance);}balance.Apply(item.Quantity);db.StockMovements.Add(new StockMovement(ret.WarehouseId,item.ProductId,item.Quantity,StockMovementType.CustomerReturn,ret.Id));}var paid=await db.Payments.Where(x=>x.SaleId==ret.SaleId&&x.Status==PaymentStatus.Paid).SumAsync(x=>(decimal?)x.Amount,ct)??0;if(paid<ret.Total){await tx.RollbackAsync(ct);return Conflict(new{message="Сумма возврата превышает подтвержденную оплату"});}ret.Complete();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{ret.Id,ret.Status,ret.Total,fiscal.ReceiptId,fiscal.FiscalNumber,paymentRefundRequired=true});}
[HttpGet("{id:guid}"),HasPermission(Permissions.SaleRefund)]public async Task<IActionResult>Get(Guid id,CancellationToken ct){var r=await db.SaleReturns.AsNoTracking().Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);return r is null?NotFound():Ok(new{r.Id,r.SaleId,r.WarehouseId,r.CashierId,r.Status,r.Total,r.Items});}}
public sealed record CreateReturnRequest(Guid SaleId,IReadOnlyList<CreateReturnItemRequest> Items);public sealed record CreateReturnItemRequest(Guid ProductId,decimal Quantity);
